<script setup lang="ts">import {computed,ref} from "vue";import {CheckCircle2,Circle,Lock} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import ZButton from "@/components/zs/ZButton.vue";import ConfirmDialog from "@/components/zs/ConfirmDialog.vue";import {formatMoney,toMinor} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";setPageMeta("Year-End Closing","Guided validation, close preview and final accounting lock.");const step=ref(1),confirmation=ref(""),dialog=ref(false),closed=ref(false);const checks=[['All bank accounts reconciled','Complete'],['Accounts receivable reviewed','Complete'],['Accounts payable reviewed','Complete'],['Inventory valuation posted','Complete'],['Depreciation and accrual journals','Review']];const canClose=computed(()=>confirmation.value==='CLOSE FY 2026');function close(){closed.value=true;dialog.value=false;step.value=4;showToast('Financial year locked','The preview close is complete; production requires backend authorization.')}</script><template><AppShell><PageHeader title="Year-End Closing" description="Guided close for FY 2026 · 01 Jul 2025 to 30 Jun 2026"><template #actions><span class="zs-badge" :class="closed?'badge-success':'badge-warning'">{{closed?'Closed':'In review'}}</span></template></PageHeader><div class="mb-4 grid gap-2 sm:grid-cols-4"><button v-for="n in 4" :key="n" class="panel flex items-center gap-2 p-3 text-left" :class="step===n?'border-primary':''" @click="step=n"><CheckCircle2 v-if="n<step||closed" class="size-4 text-success"/><Circle v-else class="size-4 text-content-muted"/><span class="text-xs font-medium">{{['Validate','Preview close','Confirm','Locked'][n-1]}}</span></button></div><Panel v-if="step===1" title="Pre-close validation" description="Resolve warnings before generating the closing journal"><ul class="divide-y divide-line"><li v-for="x in checks" :key="x[0]" class="flex items-center justify-between p-4 text-sm"><span>{{x[0]}}</span><span class="zs-badge" :class="x[1]==='Complete'?'badge-success':'badge-warning'">{{x[1]}}</span></li></ul><div class="p-4"><ZButton @click="step=2">Continue to preview</ZButton></div></Panel><Panel v-else-if="step===2" title="Closing journal preview" description="Revenue and expense balances move to retained earnings"><div class="grid gap-4 p-5 sm:grid-cols-3"><div><p class="label-caps">Close revenue</p><p class="num mt-2 text-lg font-semibold">{{formatMoney(toMinor(63940000))}}</p></div><div><p class="label-caps">Close expenses</p><p class="num mt-2 text-lg font-semibold">{{formatMoney(toMinor(42712400))}}</p></div><div><p class="label-caps">Retained earnings</p><p class="num mt-2 text-lg font-semibold text-success">{{formatMoney(toMinor(21227600))}}</p></div></div><div class="border-t border-line p-4"><ZButton @click="step=3">Continue to confirmation</ZButton></div></Panel><Panel v-else-if="step===3" title="Final confirmation" description="This action locks the financial year and cannot be undone from the frontend"><div class="max-w-lg space-y-4 p-5"><p class="text-sm text-content-secondary">Type <strong>CLOSE FY 2026</strong> to confirm. Production will require elevated permission and backend revalidation.</p><input v-model="confirmation" class="field w-full" aria-label="Closing confirmation"/><ZButton :disabled="!canClose" @click="dialog=true"><Lock class="size-4"/>Lock financial year</ZButton></div></Panel><Panel v-else title="FY 2026 closed"><div class="p-10 text-center"><CheckCircle2 class="mx-auto size-10 text-success"/><p class="mt-4 text-lg font-semibold text-content">Financial year locked</p><p class="mt-2 text-sm text-content-secondary">Closing journal preview JE-CLOSE-2026 is linked to the immutable audit history.</p></div></Panel><ConfirmDialog :open="dialog" title="Lock FY 2026?" message="No new postings will be allowed in the closed year. The backend remains authoritative." confirm-label="Lock year" tone="danger" @cancel="dialog=false" @confirm="close"/></AppShell></template>